"""The triage read side against goldens generated by the OLD code (``python -m projectzero.ops.parity_triage goldens``).

The golden holds a synthetic old data folder (inbox, proposals, routing, decision log, acceptance, auto-triage runs,
Conviction, Scout Intake, workspace override), the OLD ``triage_review.view()`` on it, the old pure rules (routing,
entity repair, portfolio check, candidate card) on 62 candidates, and the old tables. No database, no old repository.
"""

from __future__ import annotations

import json
from collections.abc import Iterator
from contextlib import contextmanager
from datetime import UTC, datetime
from decimal import Decimal
from pathlib import Path
from typing import Any

import pytest
from fastapi.testclient import TestClient

from projectzero.dealflow.ranking.tagging import PORTFOLIO as TAGGING_PORTFOLIO
from projectzero.dealflow.triage import card, portfolio_check, view
from projectzero.ops.parity_ranking import diff, js
from projectzero.ops.parity_triage import (
    checker_and_override,
    compare_goldens,
    compare_real,
    inputs_from_files,
    new_tables,
    new_units,
)

GOLDEN = json.loads(
    (Path(__file__).resolve().parents[1] / "fixtures" / "golden_v1" / "oracle_triage.json").read_text(encoding="utf-8")
)
INPUTS = inputs_from_files({k: v.encode("utf-8") for k, v in GOLDEN["files"].items()})
VIEW = js(view.build(INPUTS))
CHECKER, OVERRIDE = checker_and_override(INPUTS)
UNITS = new_units(GOLDEN["candidates"], CHECKER, OVERRIDE)


def test_provenance_is_the_clean_old_revision() -> None:
    assert GOLDEN["provenance"]["old_revision"] == "6c739b9cb6ca2517b845e381d39a36c50eccc59e"
    assert GOLDEN["provenance"]["old_dirty"] is False


def test_the_whole_golden_matches() -> None:
    assert compare_goldens(GOLDEN) == []


@pytest.mark.parametrize("table", sorted(GOLDEN["tables"]))
def test_tables_are_verbatim(table: str) -> None:
    assert diff(GOLDEN["tables"][table], js(new_tables())[table]) == []


@pytest.mark.parametrize("key", sorted(GOLDEN["units"]))
def test_pure_rules_match_the_old_code(key: str) -> None:
    assert diff(GOLDEN["units"][key], UNITS[key]) == []


def test_same_proposal_ids() -> None:
    assert VIEW["proposals"].keys() == GOLDEN["view"]["proposals"].keys()


@pytest.mark.parametrize("cid", sorted(GOLDEN["view"]["proposals"]))
def test_proposal_summary_matches_the_old_view(cid: str) -> None:
    assert diff(GOLDEN["view"]["proposals"][cid], VIEW["proposals"][cid]) == []


@pytest.mark.parametrize("key", ["architecture", "counts", "calibration", "pending", "note"])
def test_top_level_matches_the_old_view(key: str) -> None:
    assert diff(GOLDEN["view"][key], VIEW[key]) == []


# ── the golden exercises what the core Deal Flow list reads (so a broken rule cannot pass unnoticed) ──────────────
def test_the_golden_covers_every_queue_status_and_display() -> None:
    props = GOLDEN["view"]["proposals"]
    assert {s["routing"]["queue"] for s in props.values()} == {"operating", "global_only", "non_startup"}
    assert {s["portfolio"]["status"] for s in props.values()} == {
        "NONE", "KNOWN_PORTFOLIO", "PROJECT_A_RELATIONSHIP", "RESEMBLES_PORTFOLIO", "EXISTING_RECORD",
    }  # fmt: skip
    assert {s["display_proposal"] for s in props.values()} >= {"KNOWN_PORTFOLIO", "ASK_OMAR_CONFLICT", "REJECT"}
    assert any(s["stale"] for s in props.values()) and any(s["obvious_reject"] for s in props.values())
    assert any(s["queue"] for s in props.values()) and any(s["mohamed"] for s in props.values())
    assert sum(1 for s in props.values() if s["entity"]["broken"]) >= 3


def test_non_startup_and_repaired_names() -> None:
    props = VIEW["proposals"]
    assert props["uni"]["routing"] == {"queue": "non_startup", "reason": "university / academic institution"}
    assert props["incumbent"]["routing"]["reason"] == "large incumbent (rolls-royce)"
    assert props["na-eu"]["routing"]["queue"] == "operating" and props["na-global"]["routing"]["queue"] == "global_only"
    assert props["override"]["routing"]["reason"] == "Europe"  # only through workspace_geos.json
    assert props["broken-date"]["entity"]["display_name"] == "RheoCarti"
    assert props["broken-unknown"]["entity"]["display_name"] == "Kontext"


def test_queue_overlay_only_for_undecided_candidates() -> None:
    props = VIEW["proposals"]
    assert props["eu-plain"]["queue"]["state"] == "NEEDS_OPERATOR"
    assert props["baseline"]["queue"] is None  # routed, but already decided
    assert "error" not in props and "no-proposal" not in props


def test_portfolio_table_keeps_the_protected_order() -> None:
    assert [n for n, _w, _k in portfolio_check.PORTFOLIO] == [n for n, _k in TAGGING_PORTFOLIO]
    assert set(portfolio_check.PORTFOLIO_WHAT) == {n for n, _k in TAGGING_PORTFOLIO}


# ── reading pz: rows back to the old record shapes ─────────────────────────────────────────────────────────────────
def test_proposal_row_becomes_the_old_record() -> None:
    row = {"candidate_id": "abc", "run_id": "r", "prompt_version": "triage-v3", "input_sha": "s", "proposal": "KEEP",
           "status": "proposed", "model": "m", "veto_model": None, "usd": Decimal("0.000120"),
           "detail": {"reasons": ["x"], "veto": {"ok": True}}, "proposed_at": datetime(2026, 10, 9, 6, 17, 12, tzinfo=UTC),
           "is_current": True}  # fmt: skip
    p = view.proposal_record(row)
    assert p["proposed_at"] == "2026-10-09T08:17:12"  # Europe/Berlin, as the old writer stored it
    assert p["reasons"] == ["x"] and p["proposal"] == "KEEP" and p["usd"] == 0.00012 and "is_current" not in p


def test_route_and_conviction_rows() -> None:
    r = view.route_record({"state": "NEEDS_OPERATOR", "priority": 5, "reason": "why", "detail": {"at": "t", "x": 1}})
    assert r == {"at": "t", "x": 1, "state": "NEEDS_OPERATOR", "priority": 5, "reason": "why"}
    legacy = {"company": "Acme", "conflict": "none", "status": "new"}
    row = {"legacy": legacy, "attrs": {"conflict": "unclear"}, "company_name": "Acme GmbH"}
    assert view.conviction_signal(row) == {"company": "Acme", "conflict": "unclear", "status": "new"}
    assert view.conviction_signal({"legacy": None, "attrs": {}, "company_name": "New Co"}) == {"company": "New Co"}


def test_pending_ids_are_mapped_to_survivors() -> None:
    runs = {"runs": [{"pending": [{"id": "old", "reason": "r"}], "failed": []}]}
    assert view.pending_map(runs, {}, {"old": "new"}) == {"new": "TRIAGE PENDING: r"}
    assert view.pending_map(runs, {"new": {"status": "proposed"}}, {"old": "new"}) == {}
    assert view.pending_map({"runs": [{"pending": [{"no": "id"}]}]}, {}) == {}  # malformed: nothing pending
    assert view.pending_map([], {}) == {}


def test_stale_uses_the_card_hash() -> None:
    c = {"name": "Acme", "description": "d"}
    assert not card.is_stale(c, {"prompt_version": card.PROMPT_VERSION, "input_sha": card.card_sha(c)})
    assert card.is_stale(c, {"prompt_version": "triage-v2", "input_sha": card.card_sha(c)})


def test_real_comparison_excludes_only_absorbed_records() -> None:
    old = GOLDEN["view"]
    absorbed = {"eu-plain": "survivor-x"}  # pretend eu-plain (new, RESEARCH, operating) was merged away
    new = {**VIEW, "proposals": {k: v for k, v in VIEW["proposals"].items() if k != "eu-plain"}}
    counts = json.loads(json.dumps(VIEW["counts"]))
    counts["operating"]["RESEARCH"] -= 1
    new["counts"] = counts
    result = compare_real(old, new, absorbed, {"eu-plain": "new"})
    assert result["differences"] == [] and result["excluded"] == {"absorbed_by_merge": 1}
    assert compare_real(old, VIEW, {}, {})["differences"] == []
    assert compare_real(old, new, {}, {})["differences"]  # without the alias it is a real difference


# ── the route ──────────────────────────────────────────────────────────────────────────────────────────────────────
def test_route_returns_the_payload_unwrapped(monkeypatch: pytest.MonkeyPatch) -> None:
    from projectzero.api.app import create_app
    from projectzero.api.routers import dealflow_triage
    from projectzero.core.config import Settings

    @contextmanager
    def fake_transaction(_url: str) -> Iterator[object]:
        yield object()

    def fake_view(_conn: Any, schema: str) -> dict[str, Any]:
        assert schema == "pz"
        return VIEW

    monkeypatch.delenv("PZ_AUTH_TOKEN", raising=False)
    monkeypatch.delenv("PZ_ALLOWED_HOSTS", raising=False)
    monkeypatch.setattr(dealflow_triage, "transaction", fake_transaction)
    monkeypatch.setattr(dealflow_triage, "triage_view", fake_view)
    app = create_app(Settings(db_url="postgresql://nobody:nothing@127.0.0.1:1/none"))
    app.include_router(dealflow_triage.router)
    with TestClient(app, base_url="http://127.0.0.1:8177") as client:
        got = client.get("/api/deal-flow/triage")
    assert got.status_code == 200
    assert diff(GOLDEN["view"], got.json()) == []


def test_real_comparison_expects_an_absorbed_proposal_carried_to_its_survivor() -> None:
    old = GOLDEN["view"]
    carried = {**VIEW["proposals"]["eu-plain"], "candidate_id": "survivor-x", "stale": True}
    new = {
        **VIEW,
        "proposals": {**{k: v for k, v in VIEW["proposals"].items() if k != "eu-plain"}, "survivor-x": carried},
    }
    result = compare_real(old, new, {"eu-plain": "survivor-x"}, {"eu-plain": "new"}, {"survivor-x": "new"})
    assert result["differences"] == [] and result["excluded"] == {"absorbed_by_merge": 1}
    wrong = {**new, "proposals": {**new["proposals"], "survivor-x": {**carried, "proposal": "REJECT"}}}
    assert compare_real(old, wrong, {"eu-plain": "survivor-x"}, {"eu-plain": "new"}, {"survivor-x": "new"})[
        "differences"
    ]
    decided = compare_real(old, new, {"eu-plain": "survivor-x"}, {"eu-plain": "new"}, {"survivor-x": "kept"})
    assert decided["differences"]  # a decided survivor does not count, so the view's counts no longer match
